func Fibonacci() iter.Seq[uint64] {
    return func(yield func(uint64) bool) {
        a, b := uint64(0), uint64(1)
        for {
            if !yield(a) {       // consumer stopped or filtered out
                return
            }
            a, b = b, a+b
        }
    }
}
