func Fibonacci() <-chan uint64 {
    out := make(chan uint64)
    go func() {
        defer close(out)         // consumer's range ends cleanly
        for a, b := uint64(0), uint64(1); ; a, b = b, a+b {
            out <- a             // blocks until the consumer receives
        }
    }()
    return out
}
